import sys
from functools import lru_cache

def main():
    data = sys.stdin.read().split()
    s, t = data[0], data[1]
    n = len(s)

    @lru_cache(maxsize=None)
    def f(i, j, L):
        a = s[i:i + L]
        b = t[j:j + L]
        if a == b:
            return True
        if sorted(a) != sorted(b):
            return False
        for k in range(1, L):
            if f(i, j, k) and f(i + k, j + k, L - k):
                return True
            if f(i, j + L - k, k) and f(i + k, j, L - k):
                return True
        return False

    print('true' if f(0, 0, n) else 'false')

main()

