@lru_cache(maxsize=None)
def scr(a, b):
    if len(a) == 1:
        return a == b
    for k in range(1, len(a)):
        if scr(a[:k], b[:k]) and scr(a[k:], b[k:]):
            return True
        if scr(a[:k], b[len(a) - k:]) and scr(a[k:], b[:len(a) - k]):
            return True
    return False

print('true' if scr(s, t) else 'false')

